{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/lab",
  "data": [
    {
      "name": "onSelect",
      "type": "(emoji: string, option: EmojiOption) => void",
      "required": true,
      "description": "Called with the picked emoji and its option."
    },
    {
      "name": "frequentEmojis",
      "type": "readonly EmojiOption[]",
      "default": "DEFAULT_FREQUENT_EMOJIS",
      "description": "Emoji listed first, under Frequently used. An empty array leaves the row out."
    },
    {
      "name": "categories",
      "type": "readonly EmojiCategory[]",
      "description": "The emoji to offer, by group. Omit it to load the bundled set (every emoji through Emoji 15, with English CLDR names) the first time a picker mounts; pass your own for a localized or custom set."
    },
    {
      "name": "height",
      "type": "SizeValue",
      "default": "'calc(var(--spacing-8) * 10)'",
      "description": "Height of the scrolling emoji list."
    },
    {
      "name": "hasAutoFocus",
      "type": "boolean",
      "default": "false",
      "description": "Focuses the search field when the picker mounts, inline or in a Dialog. Inside a Popover, rely on the Popover’s own autofocus instead."
    },
    {
      "name": "label",
      "type": "string",
      "description": "Accessible name of the emoji list. Defaults to the localized \"Emoji\"."
    },
    {
      "name": "searchLabel",
      "type": "string",
      "description": "Placeholder and hidden label of the search field. Defaults to the localized \"Search emoji\"."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
